css:
html, body, div.page, div.art, nav[aria-label="Contents"], div.mast, div.foot, section[aria-label="Comments"], div.c, .ibox, table, th, td, .refs, ol.refs, p, li, h1, h2, a {
  background-color: #1e1f22 !important;
  color: #e6e6e6 !important;
  border-color: #3c3f44 !important;
}
a, a:visited {
  color: #8ab4f8 !important;
}
.mast, .foot, .ibox, table, th, td, div.c {
  background-color: #26282c !important;
}
input[aria-label="Search\ Openpedia"] {
  background-color: #2a2c30 !important;
  color: #e6e6e6 !important;
  border: 1px solid #4a4d52 !important;
}
button {
  background-color: #2a2c30 !important;
  color: #e6e6e6 !important;
  border-color: #4a4d52 !important;
}
